import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Inline CUDA code for fused bias subtraction + tanh
fused_bias_tanh_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_bias_tanh_kernel(const float* __restrict__ input,
                                       const float* __restrict__ bias,
                                       float* __restrict__ output,
                                       int B, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = B * C * H * W;
    if (idx < total_size) {
        int cHW = C * H * W;
        int hW = H * W;

        int b = idx / cHW;
        int r = idx % cHW;
        int c = r / hW;
        int r2 = r % hW;
        int h = r2 / W;
        int w = r2 % W;

        float val = input[idx] - bias[c];  // subtract bias
        output[idx] = tanhf(val);         // apply tanh
    }
}

torch::Tensor fused_bias_tanh_cuda(torch::Tensor input, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(),  "bias must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 4, "input must have 4 dimensions: BxCxHxW");

    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto output = torch::empty_like(input);
    int total_size = B * C * H * W;

    const int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    fused_bias_tanh_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, H, W
    );

    return output;
}
"""

fused_bias_tanh_cpp_source = r"""
torch::Tensor fused_bias_tanh_cuda(torch::Tensor input, torch::Tensor bias);
"""

# Build the custom fused operator
fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_bias_tanh_cpp_source,
    cuda_sources=fused_bias_tanh_source,
    functions=["fused_bias_tanh_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model with a transposed convolution followed by a fused bias subtraction + tanh custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape, stride=2, padding=1, output_padding=1):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size,
                                                 stride=stride, padding=padding,
                                                 output_padding=output_padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv_transpose(x)
        # Fused bias subtraction + tanh
        x = fused_ops.fused_bias_tanh_cuda(x, self.bias)
        return x

